def countOfNodes(graph, n):
    from collections import deque

    def bfs(start):
        queue = deque([(start, 0)])
        visited = [False] * n
        visited[start] = True
        even_count = 0
        while queue:
            node, dist = queue.popleft()
            if dist % 2 == 0:
                even_count += 1
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append((neighbor, dist + 1))
        return even_count

    total_even_pairs = 0
    visited = [False] * n
    for i in range(n):
        if not visited[i]:
            component_size = bfs(i)
            total_even_pairs += component_size * (component_size - 1) // 2

    return total_even_pairs // 2
